import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testPairExists() {
        Assert.assertTrue(hasPairWithSum(listOf(1, 3, 5, 7), 8))
    }

    @Test
    fun testNoPair() {
        Assert.assertFalse(hasPairWithSum(listOf(1, 2, 3), 10))
    }

    @Test
    fun testFirstAndLast() {
        Assert.assertTrue(hasPairWithSum(listOf(10, 20, 30), 40))
    }

    @Test
    fun testSmallList() {
        Assert.assertFalse(hasPairWithSum(listOf(5), 10))
    }
}
